-- Ejecutar despues de instalar TODOS los triggers y normalizar; no cambia datos.
DO $check$ DECLARE bad bigint; BEGIN
  SELECT count(*) INTO bad FROM public."Client" c LEFT JOIN public."ClientCategory" p ON p."id" = c."categoryId" WHERE c."categoryId" IS NOT NULL AND ((p."id" IS NULL OR c."storeId" <> p."storeId"));
